node <<'EOF'
const fs = require('fs');
const path = '/home/kernel-kain/Documents/Github/chesspulse/.env';
const expected = ['SMARTSPECTRA_API_KEY','CP_AI_PROVIDER','CP_AI_KEY','CP_AI_BASE_URL','CP_AI_MODEL'];
const allowedProviders = new Set(['openai','anthropic','google','opencode','custom']);
let text;
try { text = fs.readFileSync(path, 'utf8'); } catch (e) { console.log('READ_FAIL', e.code); process.exit(1); }
const lines = text.split(/\n/);
const seen = {};
const issues = [];
lines.forEach((line, i) => {
  const n = i + 1;
  const raw = line.trim();
  if (!raw || raw.startsWith('#')) return;
  const m = raw.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
  if (!m) { issues.push(`line ${n}: not a NAME=value assignment`); return; }
  const name = m[1];
  let value = m[2];
  const quoted = (value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"));
  if (quoted) value = value.slice(1, -1);
  if (seen[name]) issues.push(`${name}: duplicated`);
  seen[name] = { len: value.length, quoted, empty: value.length === 0, hasSpace: /\s/.test(value), hasBearer: /^bearer\s+/i.test(value) };
});
for (const name of expected) {
  if (!seen[name]) issues.push(`${name}: missing`);
  else if (seen[name].empty) issues.push(`${name}: empty`);
}
for (const name of Object.keys(seen)) {
  if (!expected.includes(name)) issues.push(`${name}: unexpected name`);
}
const provider = (() => {
  const raw = lines.map(l => l.trim()).find(l => /^(?:export\s+)?CP_AI_PROVIDER\s*=/.test(l));
  if (!raw) return '';
  let v = raw.replace(/^(?:export\s+)?CP_AI_PROVIDER\s*=\s*/, '');
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  return v.trim().toLowerCase();
})();
console.log('FILE_BYTES', Buffer.byteLength(text));
console.log('VARS');
for (const name of expected) {
  const s = seen[name];
  if (!s) console.log(name, 'MISSING');
  else console.log(name, s.empty ? 'EMPTY' : 'SET', 'len=' + s.len, s.quoted ? 'QUOTED' : 'PLAIN', s.hasSpace ? 'HAS_WHITESPACE' : 'NO_WHITESPACE', s.hasBearer ? 'BEARER_PREFIX' : 'NO_BEARER_PREFIX');
}
console.log('PROVIDER', provider || '(empty)');
console.log('PROVIDER_ALLOWED', provider ? String(allowedProviders.has(provider)) : 'n/a');
if (provider === 'custom' && seen.CP_AI_BASE_URL && seen.CP_AI_BASE_URL.empty) issues.push('CP_AI_BASE_URL: required for custom');
if (provider === 'opencode' || provider === 'custom') {
  console.log('BASE_URL', seen.CP_AI_BASE_URL && !seen.CP_AI_BASE_URL.empty ? 'SET' : 'EMPTY');
}
console.log('ISSUES', issues.length ? issues.join(' | ') : 'none');
EOF

