const fs = require('fs');
const path = require('path');

function parseEnv(file) {
  const out = {};
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const raw = line.trim();
    if (!raw || raw.startsWith('#')) continue;
    const m = raw.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!m) continue;
    let value = m[2];
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    out[m[1]] = value;
  }
  return out;
}

function redact(text, secrets) {
  let s = String(text ?? '');
  for (const secret of secrets) {
    if (secret && secret.length >= 6 && s.includes(secret)) s = s.split(secret).join('[redacted]');
  }
  return s.slice(0, 180);
}

const env = parseEnv('/home/kernel-kain/Documents/Github/chesspulse/.env');
const secrets = [env.SMARTSPECTRA_API_KEY, env.CP_AI_KEY].filter(Boolean);

let urlInfo = 'INVALID';
try {
  const u = new URL(env.CP_AI_BASE_URL);
  const hasUser = Boolean(u.username || u.password);
  urlInfo = `protocol=${u.protocol} host=${u.host} path=${u.pathname} userinfo=${hasUser ? 'present' : 'absent'}`;
} catch (e) {
  urlInfo = 'UNPARSEABLE';
}
console.log('OPENCODE_TARGET', urlInfo);
console.log('OPENCODE_MODEL', env.CP_AI_MODEL);

const base = env.CP_AI_BASE_URL.replace(/\/$/, '');
const modelsUrl = base + '/models';
const ac = new AbortController();
const timer = setTimeout(() => ac.abort(), 20000);
let opencode = 'NOT_RUN';
try {
  const res = await fetch(modelsUrl, {
    method: 'GET',
    headers: { Authorization: 'Bearer ' + env.CP_AI_KEY },
    signal: ac.signal,
  });
  const text = await res.text();
  let modelListed = 'unknown';
  let errorCode = '';
  try {
    const body = JSON.parse(text);
    const ids = Array.isArray(body.data) ? body.data.map(m => m.id).filter(Boolean) : [];
    if (ids.length) modelListed = ids.includes(env.CP_AI_MODEL) ? 'yes' : 'no';
    errorCode = body.error?.code || body.error?.type || body.code || '';
  } catch {
    errorCode = 'non_json';
  }
  opencode = `http=${res.status} model_listed=${modelListed} error=${errorCode || 'none'} body_bytes=${text.length}`;
} catch (e) {
  opencode = `request_failed name=${e.name} message=${redact(e.message, secrets)}`;
} finally {
  clearTimeout(timer);
}
console.log('OPENCODE_RESULT', opencode);
EOF

