class Ctrl(ctypes.Structure):
    _fields_ = [("id", ctypes.c_uint32), ("value", ctypes.c_int32)]
def ioc(nr):
    return (3 << 30) | (ord('V') << 8) | nr | (ctypes.sizeof(Ctrl) << 16)
S = ioc(28)
G = ioc(27)
fd = os.open("/dev/video0", os.O_RDWR)
