'use strict';

const { parentPort } = require('worker_threads');
const stockfish = require('stockfish');

const lines = [];
let waiter = null;

function onLine(line) {
  if (waiter && waiter.test(line)) {
    const resolve = waiter.resolve;
    waiter = null;
    resolve(line);
    return;
  }
  lines.push(line);
}

function waitFor(pattern) {
  const index = lines.findIndex((line) => pattern.test(line));
  if (index >= 0) {
    const line = lines[index];
    lines.splice(0, index + 1);
    return Promise.resolve(line);
  }
  return new Promise((resolve) => {
    waiter = {
      test: (line) => pattern.test(line),
      resolve,
    };
  });
}

const engine = stockfish('lite-single', onLine);

parentPort.on('message', async (message) => {
  if (!message || message.type !== 'run') return;
  const started = process.hrtime.bigint();
  engine.processCommand('uci');
  await waitFor(/^uciok/);
  engine.processCommand('isready');
  await waitFor(/^readyok/);
  const loadMs = Number(process.hrtime.bigint() - started) / 1e6;
  const timings = [];
  for (const fen of message.fens) {
    const mark = process.hrtime.bigint();
    engine.processCommand(`position fen ${fen}`);
    engine.processCommand(`go depth ${message.depth}`);
    const best = await waitFor(/^bestmove /);
    timings.push({
      ms: Number(process.hrtime.bigint() - mark) / 1e6,
      bestmove: best.split(/\s+/)[1] || '',
    });
    parentPort.postMessage({ type: 'progress', done: timings.length });
  }
  if (typeof engine.terminate === 'function') engine.terminate();
  parentPort.postMessage({ type: 'done', loadMs, timings });
});

'use strict';

const fs = require('fs');
const path = require('path');
const { Worker } = require('worker_threads');
const { Chess } = require('chess.js');

const depth = Number(process.argv[2] || 8);
const count = 60;
const pgnDir = path.resolve(__dirname, '../../docs/proofs/s4');
const fens = [];

for (const file of fs.readdirSync(pgnDir).filter((name) => name.endsWith('.pgn')).sort()) {
  const chess = new Chess();
  chess.loadPgn(fs.readFileSync(path.join(pgnDir, file), 'utf8'));
  fens.push(chess.fen());
  for (const move of chess.history({ verbose: true })) {
    if (move.after) fens.push(move.after);
  }
}

const unique = [];
const seen = new Set();
for (const fen of fens) {
  if (seen.has(fen)) continue;
  seen.add(fen);
  unique.push(fen);
  if (unique.length === count) break;
}

if (unique.length < count) {
  console.error(`only ${unique.length} positions`);
  process.exit(1);
}

const rss = [];
function sampleRss() {
  rss.push(process.memoryUsage().rss);
}

sampleRss();
const worker = new Worker(path.join(__dirname, 'worker.js'));
const timer = setInterval(sampleRss, 250);

const result = await new Promise((resolve, reject) => {
  worker.on('message', (message) => {
    if (message.type === 'done') resolve(message);
  });
  worker.on('error', reject);
  worker.postMessage({ type: 'run', depth, fens: unique });
});

clearInterval(timer);
sampleRss();
await worker.terminate();

const times = result.timings.map((item) => item.ms);
const sorted = [...times].sort((a, b) => a - b);
const sum = times.reduce((total, value) => total + value, 0);
const mean = sum / times.length;
const rssMb = rss.map((value) => Math.round(value / 1048576));
const summary = {
  engine: 'stockfish 19.0.1 lite-single WASM',
  depth,
  positions: times.length,
  loadMs: Math.round(result.loadMs),
  meanMs: Math.round(mean),
  maxMs: Math.round(sorted[sorted.length - 1]),
  p95Ms: Math.round(sorted[Math.ceil(sorted.length * 0.95) - 1]),
  rssStartMb: rssMb[0],
  rssMinMb: Math.min(...rssMb),
  rssMaxMb: Math.max(...rssMb),
  rssEndMb: rssMb[rssMb.length - 1],
  passMean: mean <= 150,
};

console.log(JSON.stringify(summary));
fs.writeFileSync(path.join(__dirname, 'bench-result.json'), JSON.stringify(summary, null, 2));
process.exit(summary.passMean ? 0 : 2);

