'use strict';

const { execFileSync } = require('fs');
const fs = require('fs');
const path = require('path');

function monoUs() {
  return Number(process.hrtime.bigint() / 1000n);
}

function wallMs() {
  return Date.now();
}

function dateCommandMs() {
  const text = execFileSync('date', ['+%s%3N'], { encoding: 'utf8' }).trim();
  return Number(text);
}

function monoToWallMs(mono, anchor) {
  return anchor.epochMs + (mono - anchor.monoUs) / 1000;
}

const durationMs = 120000;
const anchor = { monoUs: monoUs(), epochMs: wallMs() };
const samples = [];
const started = wallMs();

function takeSample() {
  const mono = monoUs();
  const computed = monoToWallMs(mono, anchor);
  const actual = wallMs();
  const command = samples.length % 10 === 0 ? dateCommandMs() : null;
  samples.push({
    elapsedMs: actual - started,
    errorMs: computed - actual,
    commandErrorMs: command == null ? null : computed - command,
  });
}

takeSample();
const timer = setInterval(takeSample, 1000);
setTimeout(() => {
  clearInterval(timer);
  takeSample();
  const errors = samples.map((sample) => sample.errorMs);
  const maxAbs = Math.max(...errors.map((value) => Math.abs(value)));
  const last = samples[samples.length - 1];
  const ratePerMs = last.elapsedMs > 0 ? last.errorMs / last.elapsedMs : 0;
  const projected25MinMs = ratePerMs * 25 * 60 * 1000;
  const commandErrors = samples
    .map((sample) => sample.commandErrorMs)
    .filter((value) => value != null);
  const summary = {
    samples: samples.length,
    durationMs: last.elapsedMs,
    maxAbsErrorMs: Math.round(maxAbs * 1000) / 1000,
    endErrorMs: Math.round(last.errorMs * 1000) / 1000,
    projected25MinErrorMs: Math.round(projected25MinMs * 1000) / 1000,
    maxAbsDateCommandErrorMs: commandErrors.length
      ? Math.round(Math.max(...commandErrors.map((value) => Math.abs(value))) * 1000) / 1000
      : null,
    pass: Math.abs(projected25MinMs) <= 1000 && maxAbs <= 1000,
  };
  fs.writeFileSync(path.join(__dirname, 'anchor-result.json'), JSON.stringify(summary, null, 2));
  console.log(JSON.stringify(summary));
  process.exit(summary.pass ? 0 : 2);
}, durationMs);

