// What: resolves only after the Vite process reports its own bound URL.
// Why: a free TCP connection, or a still-running npx process, can belong to another server.
// Removed: Electron could open against the wrong port or a server that failed to bind.
export function watchViteReady(vite, readyText, timeoutMs = 20000) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let output = '';
    const finish = (error) => {
      if (settled) return;
      settled = true;
      if (error) reject(error);
      else resolve();
    };
    vite.stdout?.on('data', (chunk) => {
      output += chunk.toString();
      if (output.includes(readyText)) finish();
    });
    vite.once('exit', (code) => {
      finish(new Error(`The renderer server exited before it was ready (code ${code ?? 'none'}).`));
    });
    setTimeout(() => {
      finish(new Error('The renderer server did not report that it bound port 5173.'));
    }, timeoutMs);
  });
}

import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { describe, it } from 'node:test';
import { watchViteReady } from './vite-ready.mjs';

function fakeVite() {
  const vite = new EventEmitter();
  vite.stdout = new EventEmitter();
  return vite;
}

describe('watchViteReady', () => {
  it('resolves when the owned server prints its bound URL', async () => {
    const vite = fakeVite();
    const ready = watchViteReady(vite, 'http://127.0.0.1:5173/', 200);
    vite.stdout.emit('data', '  ➜  Local:   http://127.0.0.1:5173/\n');
    await ready;
  });

  it('rejects when the server exits before binding', async () => {
    const vite = fakeVite();
    const ready = watchViteReady(vite, 'http://127.0.0.1:5173/', 200);
    vite.emit('exit', 1);
    await assert.rejects(ready, /exited before it was ready/);
  });

  it('does not accept a different port or a silent running process', async () => {
    const vite = fakeVite();
    const ready = watchViteReady(vite, 'http://127.0.0.1:5173/', 30);
    vite.stdout.emit('data', '  ➜  Local:   http://127.0.0.1:51730/\n');
    await assert.rejects(ready, /did not report that it bound/);
  });
});

